// Penalty Kings (Test) service worker: precaches every file of this build (cache name = version + content hash),
// serves them cache-first so the app works offline after the first load, and waits for the page's
// "tap to reload" before a new version takes over. Generated by scripts/build-test-app.mjs.
const CACHE = __CACHE__;
const PRECACHE = __PRECACHE__;
const VERSION = __VERSION__;

self.addEventListener("install", event => {
  event.waitUntil(caches.open(CACHE).then(cache => cache.addAll(PRECACHE.map(path => new Request(new URL(path, self.registration.scope), { cache: "reload" })))));
});

self.addEventListener("activate", event => {
  event.waitUntil((async () => {
    for (const key of await caches.keys()) if (key.startsWith("pk-test-") && key !== CACHE) await caches.delete(key);
    await self.clients.claim();
  })());
});

self.addEventListener("message", event => {
  if (event.data?.type === "SKIP_WAITING") self.skipWaiting();
  if (event.data?.type === "VERSION") event.source?.postMessage({ type: "VERSION", version: VERSION, cache: CACHE });
});

self.addEventListener("fetch", event => {
  const request = event.request;
  if (request.method !== "GET") return;
  const url = new URL(request.url);
  if (url.origin !== self.location.origin) return; // RPC and anything external: straight to the network
  event.respondWith((async () => {
    const cache = await caches.open(CACHE);
    // App navigations (including an OAuth return with ?query) get the cached shell.
    const scope = new URL(self.registration.scope);
    const isShell = request.mode === "navigate" && (url.pathname === scope.pathname || url.pathname === `${scope.pathname}index.html`);
    const hit = await cache.match(isShell ? new URL("./", scope).href : request, { ignoreSearch: true });
    if (hit) return hit;
    try {
      return await fetch(request);
    } catch (error) {
      if (request.mode === "navigate") { const shell = await cache.match(new URL("./", scope).href); if (shell) return shell; }
      throw error;
    }
  })());
});
